    <!-- Section Fitur -->
    <section id="fitur" class="features">
        <h2>Kenapa harus menggunakan TernakPro?</h2>
        <p>Masih ragu? Ini 6 alasan kenapa TernakPro pilihan terbaik untuk meningkatkan keuntungan usaha ternak Anda!</p>
        
        <div class="main-container">
            <div class="mockup-container">
                <img src="{{ asset('assets/mockup-1.png') }}" alt="Mockup TernakPro" class="mockup-image">
            </div>
            <div class="feature-cards">
                <div class="card">
                    <img src="{{ asset('assets/icon-1.png') }}" alt="Management Icon">
                    <div class="card-text">
                        <h3>Manajemen Ternak Lebih Mudah</h3>
                        <p style="color: black; font-weight: 500;">Tambah & Update data ternak tanpa ribet</p>
                    </div>
                </div>
                <div class="card">
                    <img src="{{ asset('assets/icon-4.png') }}" alt="Consultation Icon">
                    <div class="card-text">
                        <h3>Akses Konsultasi dengan Para Ahli</h3>
                        <p style="color: black; font-weight: 500;">Solusi tepat untuk pakan & perawatan ternakmu.</p>
                    </div>
                </div>
                <div class="card">
                    <img src="{{ asset('assets/icon-2.png') }}" alt="Profit Icon">
                    <div class="card-text">
                        <h3>Catat Keuangan Praktis</h3>
                        <p style="color: black; font-weight: 500;">Kontrol pemasukan & pengeluaran ternak</p>
                    </div>
                </div>
                <div class="card">
                    <img src="{{ asset('assets/icon-5.png') }}" alt="AI Icon">
                    <div class="card-text">
                        <h3>Dukungan AI Pintar</h3>
                        <p style="color: black; font-weight: 500;">Saran tepat buat pakan & perawatan ternakmu</p>
                    </div>
                </div>
                <div class="card">
                    <img src="{{ asset('assets/icon-3.png') }}" alt="Cost Icon">
                    <div class="card-text">
                        <h3>Hitung Biaya Pakan Lebih Mudah</h3>
                        <p style="color: black; font-weight: 500;">Ketahui Estimasi Pengeluaran Lebih Cepat</p>
                    </div>
                </div>
                <div class="card">
                    <img src="{{ asset('assets/icon-6.png') }}" alt="Supplier Icon">
                    <div class="card-text">
                        <h3>Akses Supplier Limbah Pakan Lebih Dekat</h3>
                        <p style="color: black; font-weight: 500;">Temukan penyedia limbah pakan dengan mudah.</p>
                    </div>
                </div>
            </div>
        </div>
